class ConfPlantillaNominalCargo extends BaseConfPlantillaNominalCargo {

	/**
     * Obtener los cargos de una plantilla nominal dado el id de plantilla.
	 *
     * @param int $idplantilla  Identificador de la plantilla nominal.
     * @return array Listado de los datos de los cargos de plantillas nominales.
     */
    public static function obtenerCargosByIdPlantilla($idplantilla) {
		//Devolviendo el listado de plantillas nominales en forma de arreglo.
        return Doctrine_Query::create()
                ->from('ConfPlantillaNominalCargo')
                ->where('activo = true and idplantillanominal = ?', array($idplantilla))
                ->orderBy('ordenunico')
                ->fetchArray();
    }
	
	/**
     * Obtener los cargos de una plantilla nominal dado el id de plantilla.
	 *
     * @param int $idplantilla  Identificador de la plantilla nominal.
     * @return array Listado de los datos de los cargos de plantillas nominales.
     */
    public static function getCargos($identidad,$areas) {
		
        //Devolviendo el listado de plantillas nominales en forma de arreglo.
        return Doctrine_Query::create()
				->select('cpnc.idcargo,cpn.idarea as idarea,na.denominacion as area')	
                ->from('ConfPlantillaNominalCargo cpnc')
				->innerJoin('cpnc.ConfPlantillaNominal cpn')
				->innerJoin('cpn.NomAreas na')
				->where("cpn.idarea=$areas and cpn.identidad = $identidad")
                ->orderBy('cpn.orden ASC')
                ->fetchArray();
    }
	
	/**
     * Obtener los cargos de las plantillas que pertenecen a una entidad especificada.
	 *
     * @param int $identidad  Identificador de la entidad.
     * @return array Listado de los cargos de las entidades.
     */
    public static function obtenerCargosRegistradorByIdEstruc($identidad) {
		
        //Devolviendo el listado de cargos registrados en forma de arreglo.
        return Doctrine_Query::create()->select('pc.idcargo')
                ->from('ConfPlantillaNominalCargo pc')
		->innerJoin('pc.ConfPlantillaNominal pn')
                ->where('pn.identidad =? and pn.fechafin is null',array($identidad))
                ->fetchArray();
    }


	/**
     * Eliminar un array de cargos dado el id de plantilla nominal.
	 *
     * @param int $idplantilla  Identificador de la plantilla nominal.
	 * @param array $array  	Array de cargos a eliminar.
     */
    public static function eliminarArrayCargos($idplantilla, $array) {
        // if(count($array)>0){
        //     $deleted = Doctrine_Query::create()
        //         ->delete()
        //         ->from('ConfPlantillaNominalCargo pc on pc.idplantillanominal = ?', $idplantilla)
        //         ->whereIn('pc.idcargo', $array)
        //         ->execute ();
        // }
        $sql = "DELETE FROM 
            mod_nomina.conf_plantillanominalcargo WHERE idplantillanominal = $idplantilla and idcargo in (" . implode(', ', $array) . ");";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $conn->execute($sql);
	}

    /**
     * Obtener un listado de los datos de las plantillas nominales dado un identificador de entidad.
	 *
     * @param int $identidad  Identificador de la entidad.
     * @return array Listado de los datos de las plantillas nominales.
     */
    public static function obtenerListadoPlantillasNominales($identidad) {

        //Devolviendo el listado de plantillas nominales en forma de arreglo.
        return Doctrine_Query::create()
                ->from('ConfPlantillaNominal')
                ->where('identidad = ?', array($identidad))
                ->orderBy('orden ASC')
                ->fetchArray();
    }

    /**
     * Obtener la plantilla nominal dado el identificador.
     * 
     * @param $idplantilla        		Identificador de la plantilla nominal.
     * @return ConfPlantillaNominal   	Objeto plantilla nominal (clase del dominio).
     */
    public static function obtenerObjPlantillaNominalDadoId($idplantilla) {
        return Doctrine::getTable('ConfPlantillaNominal')->find($idplantilla);
    }
    
    /*Devuelve las personas que ocupan cargos en la plantilla y que cobran por caja o cajero*/
    public static function obtenerPersonaPlantillaOcupanCargosCajeroCaja($idplantilla, $cajacajero, $tipomoneda){
	    $where = "";
		if($cajacajero == 1 && $tipomoneda == 1){
		  $where = "and dco.idpersonacuentabancariamn is null";
		}else if($cajacajero == 1 && $tipomoneda == 2){
		  $where = "and dco.idpersonacuentabancariacuc is null";
		}else if($cajacajero == 2 && $tipomoneda == 1){
		  $where = "and dco.idpersonacuentabancariamn is not null";
		}else if($cajacajero == 2 && $tipomoneda == 2){
		  $where = "and dco.idpersonacuentabancariacuc is not null";
		}
		$sql = "select dco.idcargosocupados, dco.idpersona, dco.idcargo, dco.idsituacionlaboral
					from mod_nomina.conf_plantillanominalcargo pnc
					inner join mod_nomina.dat_cargosocupados dco on (dco.idcargo = pnc.idcargo)
					where pnc.idplantillanominal = ?
					".$where.";";// and (dco.fechavencimiento >= now() or dco.fechavencimiento is null)
		$mg = Doctrine_Manager::getInstance();
		$conn = $mg->getCurrentConnection();
		$r = $conn->fetchAll($sql, array($idplantilla));
		return $r;
	}

    public function obtenerPlantillaXIdCargo($idcargo){
        $sql = Doctrine_Query::create();
        $sql->select('p.idplantillanominal, p.denominacion, pnc.*')
            ->from('ConfPlantillaNominalCargo pnc')
            ->innerJoin('pnc.ConfPlantillaNominal p')
            ->where('pnc.idcargo = ?', array($idcargo));
        return $sql->fetchArray();
    }

    public function obtenerDenomPlantillaXIdCargo($idcargo){
        $sql = Doctrine_Query::create();
        $sql->select('p.denominacion as denominacion')
            ->from('ConfPlantillaNominalCargo pnc')
            ->innerJoin('pnc.ConfPlantillaNominal p')
            ->where('pnc.idcargo = ?', array($idcargo));
        return $sql->fetchOne()->denominacion;
    }

    public static function obtenerCentroCostoCargo($idcargo){
        $sql = "select pn.idcentrocosto
					from mod_nomina.conf_plantillanominalcargo pnc
					inner join mod_nomina.conf_plantillanominal pn on (pn.idplantillanominal = pnc.idplantillanominal)
					where pnc.idcargo = ?";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $r = $conn->fetchAll($sql, array($idcargo));
        return $r;
    }

    public static function obtenerCantidadCargoXPlantillaNominal($idcargo){
        $sql = "select count(pnc.idplantillanominalcargo)
					from mod_nomina.conf_plantillanominalcargo pnc
					inner join mod_nomina.conf_plantillanominal pn on (pn.idplantillanominal = pnc.idplantillanominal)
					where pnc.idcargo = ?";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $r = $conn->fetchOne($sql, array($idcargo));
        return $r;
    }

    public static function obtenerOrdenMaximoPlantillaNominal($identidad){
        $sql = "select max(orden)
					from mod_nomina.conf_plantillanominalcargo
					where identidad = ?";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $r = $conn->fetchOne($sql, array($identidad));
        return $r;
    }
}
